head.script:
///////// 1. 변수 및 선언 영역 /////////

// [수정]시 첨부파일 실제 삭제 여부
scwin.isRealDeleteYn = "N";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 진입 시 공시담당자 정보를 조회하고, 게시물ID 파라미터 유무에 따라 신규 작성/수정 상세조회 모드로 화면을 구성한다.
 * @returns {void}
 * @hidden N
 * @example (body ev:onpageload 바인딩으로 자동 호출)
 */
scwin.onpageload = async function() {

    // 공시담당자 정보
    const sbmOptions = {
        id : "sbm_SelectDisclsChrgList",
        action : "/api/discls/support/qna/discls-chrg/select-list",
        method : "get",
        target : "dlt_DisclsChrgList=body",
        isProcessMsg : false
    };
    await await $c.sbm.executeDynamic(sbmOptions);

    const contnId = $c.data.getParameter("contnId");
    if(!contnId) { // 신규
        const comNm = $c.session.info("comAbbrv");
        txt_comNm.setValue(comNm);

        // 버튼
        btn_update.hide();

        // 첨부파일 다운로드 row 안보이게
        grp_quesAttachFile.hide();

    } else {
        // [수정] 상세조회
        btn_insert.hide();

        dma_QnaInfo.set("contnId", contnId);
        const sbmOptions = {
            id : "sbm_SelectQna",
            action : "/api/discls/support/qna/select-one",
            method : "get",
            ref : "dma_QnaInfo",
            target : "dma_QnaInfo=body",
            isProcessMsg : false
        };
        await await $c.sbm.executeDynamic(sbmOptions);
    }

};

///////// 3. 컴포넌트 이벤트 영역 /////////
/// EVENT ///

/**
 * @method
 * @name rd_data_yn_onchange
 * @description 등록자 정보 선택 — 선택 값에 따라 등록자명 입력방법(콤보박스/입력박스)을 전환한다.
 * @param {Object} info 변경 정보 객체(newValue: 선택 값)
 * @returns {void}
 * @hidden N
 * @example scwin.rd_data_yn_onchange(info);
 */
scwin.rd_data_yn_onchange = function (info) {
    scwin.inCharge(info.newValue);
};

/**
 * @method
 * @name sel_chrgNm_onchange
 * @description 등록자명 콤보박스 선택 — 선택한 담당자의 연락처, 이메일을 세팅한다.
 * @param {Object} info 변경 정보 객체(newValue: 담당자구분코드)
 * @returns {void}
 * @hidden N
 * @example scwin.sel_chrgNm_onchange(info);
 */
scwin.sel_chrgNm_onchange = function (info) {
    scwin.selCharge(info.newValue);
};

/**
 * @method
 * @name ipt_quesContn_onkeyup
 * @description 질의 내용 입력 — 내용을 작성 할때마다 글자수(byte)를 계산해 출력한다(최대 2000byte).
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.ipt_quesContn_onkeyup(e);
 */
scwin.ipt_quesContn_onkeyup = function (e) {
    scwin.checkByte(ipt_quesContn);
};

/**
 * @method
 * @name txt_quesAttachFileNm_onclick
 * @description 수정폼 첨부파일명 클릭 — 게시물ID·첨부파일일련번호로 파일을 다운로드한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.txt_quesAttachFileNm_onclick(e);
 */
scwin.txt_quesAttachFileNm_onclick = function (e) {
    const contnId = dma_QnaInfo.get("contnId");
    const contnAttachSeq = dma_QnaInfo.get("contnAttachSeq");
    scwin.fileDown(contnId, contnAttachSeq);
};

/**
 * @method
 * @name btn_deleteFile_onclick
 * @description 파일 삭제 버튼 클릭 — 첨부파일을 삭제 처리한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.btn_deleteFile_onclick(e);
 */
scwin.btn_deleteFile_onclick = function (e) {
    scwin.deleteAttachFile();
};

/**
 * @method
 * @name btn_fileUp_onclick
 * @description 첨부파일 버튼 클릭 — 파일 선택 대화상자를 연다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.btn_fileUp_onclick(e);
 */
scwin.btn_fileUp_onclick = function (e) {
    upd_compUpload.openFileDialog();
};

/**
 * @method
 * @name upd_compUpload_oninputvaluechange
 * @description 파일 변경 — 선택한 파일명을 첨부파일 표시 입력박스에 세팅한다.
 * @param {String} fileName 선택한 파일명
 * @returns {void}
 * @hidden N
 * @example scwin.upd_compUpload_oninputvaluechange("file.hwp");
 */
scwin.upd_compUpload_oninputvaluechange = function (fileName) {
    txt_presentAttachFile.setValue(fileName);
};

/**
 * @method
 * @name btn_list_onclick
 * @description 목록 버튼 클릭 — Q&A 목록화면으로 이동한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.btn_list_onclick(e);
 */
scwin.btn_list_onclick = function (e) {
    scwin.goList();
};

/**
 * @method
 * @name btn_insert_onclick
 * @description 신청 버튼 클릭(신규등록) — 작성한 내용을 신규 등록한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.btn_insert_onclick(e);
 */
scwin.btn_insert_onclick = function (e) {
    scwin.register("I");
};

/**
 * @method
 * @name btn_update_onclick
 * @description 저장 버튼 클릭(수정저장) — 작성한 내용을 수정 저장한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.btn_update_onclick(e);
 */
scwin.btn_update_onclick = function (e) {
    scwin.register("U");
};

///////// 4. 서브미션 콜백 영역 /////////
/// SUBMISSION ///

/**
 * @method
 * @name sbm_SelectQna_submitdone
 * @description [수정] 상세조회 성공 콜백 — 등록자명이 담당자정보에 있으면 selectbox, 없으면 수동입력으로 세팅하고 첨부파일 영역을 구성한다.
 * @param {Object} e 서브미션 응답 객체
 * @returns {void}
 * @hidden N
 * @example scwin.sbm_SelectQna_submitdone(sbmRtn);
 */
scwin.sbm_SelectQna_submitdone = function (e) {
    const res = e.responseJSON;
    const body = res.body;
    const questrNm = body.questrNm;

    // 등록자명 세팅
    let chrgTpCd = "";
    const selChrgNmCnt = dlt_DisclsChrgList.getRowCount();
    for (let i = 0; i < selChrgNmCnt; i++){
        const item = dlt_DisclsChrgList.getRowJSON(i);
        if(item.chrgNm === questrNm) {
            chrgTpCd = item.chrgTpCd;
        }
    }

    // 담당자정보에 있으면 selectbox, 없으면 수동입력
    if(!chrgTpCd) {
        rd_data_yn.setValue("Y");// 수동입력
        ipt_chrgNm.setValue(dma_QnaInfo.get("questrNm"));
    } else {
        rd_data_yn.setValue("N");
        sel_chrgNm.setValue(chrgTpCd);
    }

    // 첨부파일
    const attachFileNm = body.attachFileNm;
    if(!attachFileNm) {
        scwin.showAttachFile(true);

    } else {
        scwin.showAttachFile(false);
    }
};

/**
 * @method
 * @name sbm_InsertQna_submitdone
 * @description 신규신청 성공 후 첨부파일 Insert — 신규일 경우 parameter : contnId, File, yn=N
 * @param {Object} e 서브미션 응답 객체
 * @returns {void}
 * @hidden N
 * @example scwin.sbm_InsertQna_submitdone(sbmRtn);
 */
scwin.sbm_InsertQna_submitdone = function (e) {
    const res = e.responseJSON;

    // 성공 후 첨부파일 전송
    if(res && res.body && txt_presentAttachFile.getValue()) {
        scwin.upload(res.body, "N");
    }
};

/**
 * @method
 * @name sbm_UpdateQna_submitdone
 * @description 수정 성공 후 첨부파일 Insert/Update/Delete —
 *              1.(신규) contnId, File, yn=N
 *              2.새 파일 선택(수정) seq, yn=Y, file
 *              3.새 파일 없음(삭제) seq, yn=Y
 *              4.첨부파일 추가/수정/삭제 없음(유지)
 * @param {Object} e 서브미션 응답 객체
 * @returns {void}
 * @hidden N
 * @example scwin.sbm_UpdateQna_submitdone(sbmRtn);
 */
scwin.sbm_UpdateQna_submitdone = function (e) {
    const res = e.responseJSON;
    const seq = dma_QnaInfo.get("contnAttachSeq");
    if(res && res.body) {
        if(!seq) { // 신규
            scwin.upload(res.body, "N");
        } else {
            // CASE 2~3
            if(scwin.isRealDeleteYn === "Y") {
                scwin.upload(res.body, "Y");
            } else {
                // CASE4.유지
                scwin.goList();
            }
        }
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/// FUNCTION ///

/**
 * @method
 * @name goList
 * @description 목록으로 이동 — Q&A 목록화면으로 이동한다.
 * @returns {void}
 * @hidden N
 * @example scwin.goList();
 */
scwin.goList = function () {
    const moveUrl = "/ui/dis/support/JLDFIL17300.xml";
    $c.win.moveUrl(moveUrl, {});
};

/**
 * @method
 * @name register
 * @description 저장 — 등록자 정보 입력방법에 따라 등록자명을 세팅하고 필수 항목 검증 후 신규등록(I)/수정(U) 서브미션을 실행한다.
 * @param {String} flag 처리 구분(I: 신규등록, U: 수정저장)
 * @returns {void}
 * @hidden N
 * @example await scwin.register("I");
 */
scwin.register = async function (flag) {
    let q_name = "";
    const in_data_yn = rd_data_yn.getValue();

    // 등록자명
    if(in_data_yn === "N") { // 담당자정보
        q_name = sel_chrgNm;

        if(!q_name.getValue()) {
            ipt_questrTelNo.setValue("");
            ipt_questrEmail.setValue("");
            alert("'등록자명' 항목을 선택하세요.");
            q_name.focus();
            return;
        }
        dma_QnaInfo.set("questrNm", q_name.getText());

    } else if(in_data_yn === "Y") { // 수동입력
        q_name = ipt_chrgNm;

        if(scwin.nullChk(q_name)) {
            return ;
        }
        dma_QnaInfo.set("questrNm", q_name.getValue());

    } else {
        alert("'등록자 정보'를 선택하세요.");
        rd_data_yn.focus();
        return;
    }

    if(scwin.nullChk(ipt_questrTelNo)) {
        return;
    }

    if(scwin.nullChk(ipt_questrEmail)) {
        return;
    }

    if(scwin.nullChk(sel_quesBzTpCd)) {
        return;
    }

    if(scwin.nullChk(ipt_quesTitle)) {
        return;
    }

    if(scwin.nullChk(ipt_quesContn)) {
        return;
    }

    if(flag === "I") {
        const sbmOptions = {
            id : "sbm_InsertQna",
            action : "/api/discls/support/qna/insert",
            ref : "dma_QnaInfo",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        scwin.sbm_InsertQna_submitdone(sbmRtn);

    } else if(flag === "U") {
        const sbmOptions = {
            id : "sbm_UpdateQna",
            action : "/api/discls/support/qna/update",
            ref : "dma_QnaInfo",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        scwin.sbm_UpdateQna_submitdone(sbmRtn);
    }
};

/**
 * @method
 * @name inCharge
 * @description 등록자 정보 선택 시, 등록자명 입력방법 변경 — 수동입력(Y)이면 입력박스, 담당자정보(N)이면 콤보박스를 표시한다.
 * @param {String} val 등록자 정보 선택 값(Y: 수동입력, N: 담당자정보)
 * @returns {void}
 * @hidden N
 * @example scwin.inCharge("Y");
 */
scwin.inCharge = function (val) {
    // ipt_questrTelNo.setValue("");
    // ipt_questrEmail.setValue("");

    if(val === "Y") {
        sel_chrgNm.setValue("");
        sel_chrgNm.hide();
        ipt_chrgNm.show("");
    } else {
        ipt_chrgNm.setValue("");
        sel_chrgNm.show("");
        ipt_chrgNm.hide();
    }
};

/**
 * @method
 * @name selCharge
 * @description 등록자명 변경 시 — 선택한 담당자구분코드로 담당자 목록에서 연락처, 이메일을 찾아 세팅한다(미선택 시 초기화).
 * @param {String} chrgTpCd 담당자구분코드
 * @returns {void}
 * @hidden N
 * @example scwin.selCharge(chrgTpCd);
 */
scwin.selCharge = function (chrgTpCd) {
    let selectedData;

    const disclsChrgList = dlt_DisclsChrgList.getAllJSON();
    for (let i = 0; i < disclsChrgList.length; i++){
        const item = disclsChrgList[i];
        if(item.chrgTpCd === chrgTpCd) {
            selectedData = item;
        }
    }

    if(!selectedData) {
        dma_QnaInfo.set("questrTelNo", "");
        dma_QnaInfo.set("questrEmail", "");

    } else {
        dma_QnaInfo.set("questrTelNo", selectedData.telNo);
        dma_QnaInfo.set("questrEmail", selectedData.email);
    }
};

/**
 * @method
 * @name showAttachFile
 * @description 첨부파일 영역 업로드 가능/불가능하게 전환한다.
 * @param {Boolean} isUpload 업로드 가능 여부(true: 업로드가능)
 * @returns {void}
 * @hidden N
 * @example scwin.showAttachFile(true);
 */
scwin.showAttachFile = function (isUpload) {
    if(isUpload) {
        grp_attachFile.hide();
        grp_nofileMessage.show("");

        grp_upload.show("");
        grp_message.hide();
    } else {
        grp_attachFile.show("flex");
        grp_nofileMessage.hide();

        grp_upload.hide();
        grp_message.show("");
    }
};

/**
 * @method
 * @name fileDown
 * @description 첨부파일 다운로드 — 게시물ID·첨부파일일련번호로 파일 다운로드를 요청한다.
 * @param {String} contnId 게시물ID
 * @param {String} contnAttachSeq 첨부파일일련번호
 * @returns {void}
 * @hidden N
 * @example scwin.fileDown(contnId, contnAttachSeq);
 */
scwin.fileDown = function (contnId, contnAttachSeq) {
    $p.download("/api/discls/support/qna/file/download?contnId="+contnId+"&contnAttachSeq="+contnAttachSeq, {}, "get", true);
};

/**
 * @method
 * @name deleteAttachFile
 * @description 첨부파일 삭제 — 실제 삭제 여부 플래그를 세팅하고 첨부파일 영역을 업로드 가능 상태로 전환한다.
 * @returns {void}
 * @hidden N
 * @example scwin.deleteAttachFile();
 */
scwin.deleteAttachFile = function () {
    scwin.isRealDeleteYn = "Y"; // [수정]시 첨부파일 변경사항 있었는지 확인여부
    scwin.showAttachFile(true);
};

/**
 * @method
 * @name upload
 * @description 파일업로드 전송 — 게시물ID·첨부파일일련번호·삭제여부 파라미터를 추가해 업로드 후 목록으로 이동한다.
 * @param {String} contnId 게시물ID
 * @param {String} deleteAttachFileYn 첨부파일 삭제여부(Y/N)
 * @returns {void}
 * @hidden N
 * @example await scwin.upload(contnId, "N");
 */
scwin.upload = async function (contnId, deleteAttachFileYn) {
    upd_compUpload.addParam("contnId", contnId);
    upd_compUpload.addParam("contnAttachSeq", dma_QnaInfo.get("contnAttachSeq"));
    upd_compUpload.addParam("deleteAttachFileYn", deleteAttachFileYn);

    await upd_compUpload.submit();

    await scwin.goList();
};

// TODO : 추후 common.js 사용으로 변경------------------------------------------------------------------------------------------

/**
 * @method
 * @name isNull
 * @description 항목 입력 사항 Null 체크 — 값이 비어있으면 안내 후 포커스를 이동한다.
 * @param {Object} _obj 검사 대상 컴포넌트
 * @param {String} _msg 안내 메시지에 표시할 항목명
 * @returns {Boolean} 빈 값 여부(true: 비어있음)
 * @hidden N
 * @example if (scwin.isNull(ipt_quesTitle, "제목")) return;
 */
scwin.isNull = function (_obj, _msg) {
    if(!_obj || $c.str.trim(_obj.getValue()) === '' || _obj.getValue() === null) {
        alert("'" + _msg + "' 항목을 입력하세요.");
        _obj.focus();
        return true;
    }
    return false;
};

/**
 * @method
 * @name nullChk
 * @description Null 체크 — 컴포넌트의 title 속성을 항목명으로 하여 입력 사항 Null 체크를 수행한다.
 * @param {Object} _obj 검사 대상 컴포넌트
 * @returns {Boolean} 빈 값 여부(true: 비어있음)
 * @hidden N
 * @example if (scwin.nullChk(ipt_quesTitle)) return;
 */
scwin.nullChk = function (_obj) {
    return scwin.isNull(_obj, _obj.getAttribute("title"));
};

/**
 * @method
 * @name checkByte
 * @description 내용 바이트 계산, 초과시 초과 내용 삭제 — 글자수(byte)를 표시하고 2000byte 초과 시 초과분을 자동 삭제한다.
 * @param {Object} _obj 검사 대상 textarea 컴포넌트
 * @returns {void}
 * @hidden N
 * @example scwin.checkByte(ipt_quesContn);
 */
scwin.checkByte = function (_obj) {
    // 기준바이트 수
    const standardByte = 2000;		// 2000B 제한
    const contnByte = scwin.getByte(_obj);

    txt_byteCnt.setValue("질의내용<br>(" + (contnByte) + "/2000 byte)");

    if(contnByte > standardByte){
        alert( (contnByte - standardByte) + "바이트가 초과되었습니다. 초과된 내용은 자동삭제됩니다.\n");
        const contnValue = _obj.getValue();

        // 초과한 문자열을 삭제
        _obj.setValue(scwin.calcContn(contnValue, standardByte));

        // 바이트수를 재계산
        scwin.checkByte(_obj);
    }
};

/**
 * @method
 * @name getByte
 * @description 바이트수 구하기 — 내용의 바이트 수를 계산한다(enter·한글 2byte 처리).
 * @param {Object} _obj 검사 대상 컴포넌트
 * @returns {Number} 내용 바이트 수
 * @hidden N
 * @example const contnByte = scwin.getByte(ipt_quesContn);
 */
scwin.getByte = function (_obj) {
    const sTmpCntnt = new String(_obj.getValue());	// 내용 저장 변수

    let iCounts = 0;	// 바이트 수 저장 변수

    for (let i = 0 ;i < sTmpCntnt.length; i++) {
        //  16 진수 변환
        const escapeChar = escape(sTmpCntnt.charAt(i));

        if (escapeChar === '%0A') {	// enter 처리
            iCounts += 2;
        } else if (escapeChar.length > 4) {	// 한글 2byte 처리
            iCounts += 2;
        } else  {
            iCounts++;
        }
    }
    return iCounts;
};

/**
 * @method
 * @name calcContn
 * @description 초과 바이트 정리 — 최대 바이트 수를 넘지 않는 범위까지의 문자열을 잘라 반환한다.
 * @param {String} _contn 원본 내용 문자열
 * @param {Number} _maximum 최대 바이트 수
 * @returns {String} 최대 바이트 이내로 정리된 문자열
 * @hidden N
 * @example const cut = scwin.calcContn(contnValue, 2000);
 */
scwin.calcContn = function (_contn, _maximum) {
    let rContn = "";
    let nbytes = 0;	// 총 byte 수

    for (let i=0; i<_contn.length; i++) {
        const ch = _contn.charAt(i);

        let inc = 0;	// 증가치 변수

        if (escape(ch) === '%0A') {
            inc = 2;
        }else if (escape(ch).length > 4) {
            inc = 2;
        } else {
            inc = 1;
        }

        nbytes += inc;

        if (nbytes > _maximum) {	// _maximum 넘어서면 break
            break;
        }

        rContn += ch;	// ch 추가
    }

    return rContn;
};
